    obtain ⟨X, hX₁⟩ := lindenbaum (S := φ.subformulae) (X := {-φ})
      (by
        simp only [Formulae.complementary, Finset.singleton_subset_iff, Finset.mem_union, Finset.mem_image];
        right;
        use φ;
        constructor <;> simp;
